cat <<'EOF' > app/javascript/helpers/date_helpers.js
import { getMetaContent } from "helpers/meta_helpers"

const MS_PER_DAY = 1000 * 60 * 60 * 24

const timeFormatter = new Intl.DateTimeFormat("en-US", { timeStyle: "short" })
const shortDateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" })
const longDateFormatter = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" })
const weekdayFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" })
const weekdayWithYearFormatter = new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })
const dateTimeFormatter = new Intl.DateTimeFormat("en-US", { dateStyle: "short", timeStyle: "short" })
const fullDateTimeFormatter = new Intl.DateTimeFormat("en-US", { dateStyle: "medium", timeStyle: "short" })
const relativeTimeFormatter = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })

export function formatLocalTime(date, style = "time", now = new Date()) {
  switch (style) {
    case "time":
      return normalizeSpaces(timeFormatter.format(date))
    case "date":
      return longDateFormatter.format(date)
    case "shortdate":
      return formatShortDate(date, now)
    case "datetime":
      return normalizeSpaces(dateTimeFormatter.format(date))
    case "ago":
      return formatAgo(date, now)
    case "indays":
      return formatInDays(date, now)
    case "agoorweekday":
      return formatAgoOrWeekday(date, now)
    default:
      return normalizeSpaces(timeFormatter.format(date))
  }
}

export function formatFullDateTime(date) {
  return normalizeSpaces(fullDateTimeFormatter.format(date))
}

export function formatShortDate(date, now = new Date()) {
  if (date.getFullYear() === now.getFullYear()) {
    return shortDateFormatter.format(date)
  } else {
    return longDateFormatter.format(date)
  }
}

export function localDifferenceInDays(fromDate, toDate) {
  return Math.round((localBeginningOfDay(toDate) - localBeginningOfDay(fromDate)) / MS_PER_DAY)
}

function localBeginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

function formatAgo(date, now) {
  const daysAgo = localDifferenceInDays(date, now)

  if (daysAgo === 0) {
    return normalizeSpaces(timeFormatter.format(date))
  } else if (daysAgo === 1) {
    return relativeTimeFormatter.format(-1, "day")
  } else if (daysAgo > 1 && daysAgo < 7) {
    return relativeTimeFormatter.format(-daysAgo, "day")
  } else if (daysAgo >= 7) {
    return formatShortDate(date, now)
  } else {
    return relativeTimeFormatter.format(-daysAgo, "day")
  }
}

function formatInDays(date, now) {
  const daysUntil = localDifferenceInDays(now, date)

  if (daysUntil <= 0) {
    return relativeTimeFormatter.format(0, "day")
  } else {
    return relativeTimeFormatter.format(daysUntil, "day")
  }
}

function formatAgoOrWeekday(date, now) {
  const daysAgo = localDifferenceInDays(date, now)

  if (daysAgo === 0) {
    return relativeTimeFormatter.format(0, "day")
  } else if (daysAgo === 1) {
    return relativeTimeFormatter.format(-1, "day")
  } else if (date.getFullYear() === now.getFullYear()) {
    return weekdayFormatter.format(date)
  } else {
    return weekdayWithYearFormatter.format(date)
  }
}

function normalizeSpaces(string) {
  return string.replace(/\u202f/g, " ")
}

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MS_PER_DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

let dateFormatterCache
let dateFormatterTimezone

function dateFormatter() {
  const timezone = getMetaContent("timezone")

  if (!dateFormatterCache || dateFormatterTimezone !== timezone) {
    dateFormatterTimezone = timezone
    dateFormatterCache = buildDateFormatter(timezone)
  }

  return dateFormatterCache
}

function buildDateFormatter(timezone) {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }

  try {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat("en-US", options)
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/local_time_controller.js
import { Controller } from "@hotwired/stimulus"
import { formatFullDateTime, formatLocalTime } from "helpers/date_helpers"

const REFRESH_INTERVAL = 60_000
const connectedControllers = new Set()
let refreshTimer = null

function startRefreshing() {
  if (refreshTimer) return

  refreshTimer = setInterval(refreshAll, REFRESH_INTERVAL)
  document.addEventListener("visibilitychange", handleVisibilityChange)
  document.addEventListener("turbo:before-morph-element", handleBeforeMorphElement)
  document.addEventListener("turbo:morph", refreshAll)
}

function stopRefreshing() {
  if (!refreshTimer) return

  clearInterval(refreshTimer)
  refreshTimer = null
  document.removeEventListener("visibilitychange", handleVisibilityChange)
  document.removeEventListener("turbo:before-morph-element", handleBeforeMorphElement)
  document.removeEventListener("turbo:morph", refreshAll)
}

function handleVisibilityChange() {
  if (document.visibilityState === "visible") {
    refreshAll()
  }
}

function handleBeforeMorphElement(event) {
  const newElement = event.detail?.newElement
  if (newElement?.dataset?.controller?.split(/\s+/).includes("local-time")) {
    applyLocalTime(newElement)
  }
}

function refreshAll() {
  for (const controller of connectedControllers) {
    controller.refresh()
  }
}

function applyLocalTime(element) {
  const rawDatetime = element.dataset.localTimeDatetimeValue || element.getAttribute("datetime")
  if (!rawDatetime) return

  const date = new Date(rawDatetime)
  if (Number.isNaN(date.getTime())) return

  const style = element.dataset.localTimeStyleValue || "time"
  const formatted = formatLocalTime(date, style)
  const targetAttribute = element.dataset.localTimeAttributeValue

  if (targetAttribute) {
    if (element.getAttribute(targetAttribute) !== formatted) {
      element.setAttribute(targetAttribute, formatted)
    }
  } else {
    if (element.textContent !== formatted) {
      element.textContent = formatted
    }
    if (!element.hasAttribute("title") || element.dataset.localTimeTitled) {
      const title = formatFullDateTime(date)
      if (element.title !== title) {
        element.title = title
      }
      element.dataset.localTimeTitled = "true"
    }
  }
}

export default class extends Controller {
  static values = {
    datetime: String,
    style: { type: String, default: "time" },
    attribute: String
  }

  connect() {
    connectedControllers.add(this)
    startRefreshing()
    this.refresh()
  }

  disconnect() {
    connectedControllers.delete(this)
    if (connectedControllers.size === 0) {
      stopRefreshing()
    }
  }

  datetimeValueChanged() {
    this.refresh()
  }

  styleValueChanged() {
    this.refresh()
  }

  refresh() {
    applyLocalTime(this.element)
  }
}
EOF

cat <<'EOF' > app/helpers/bridge_helper.rb
module BridgeHelper
  def bridge_icon(name)
    asset_url("#{name}.svg")
  end

  def bridged_button_to_board(board)
    link_to "Go to #{board.name}", board, hidden: true, data: {
      bridge__buttons_target: "button",
      bridge_icon_url: bridge_icon("board"),
      bridge_title: "Go to #{board.name}"
    }
  end

  def bridged_share_url_button(description = nil)
    if description.is_a?(Hash)
      description_text = description[:text]
      extra_data = description.except(:text)
    else
      description_text = description
      extra_data = {}
    end

    tag.button "Share", hidden: true, data: {
      controller: "bridge--share",
      action: "bridge--share#shareUrl",
      bridge__overflow_menu_target: "item",
      bridge_title: "Share",
      bridge_share_description: description_text,
      **extra_data
    }
  end

  def bridge_share_card_description(card)
    author = card.creator.familiar_name
    assignees = card.assignees.any? ? "assigned to #{card.assignees.map { |assignee| h assignee.familiar_name }.to_sentence}" : "not assigned"
    {
      text: "Added %{added} by #{author} and #{assignees}. Updated %{updated}",
      bridge__share_dates_value: {
        added: card.created_at.utc.iso8601,
        updated: card.last_active_at.utc.iso8601
      }.to_json
    }
  end

  def bridge_share_board_description(board)
    count_open = board.cards.active.count
    count_in_stream = board.cards.awaiting_triage.count
    "#{count_open} open cards, #{count_in_stream} in MAYBE?"
  end
end
