cat <<'EOF' > app/javascript/controllers/bridge/share_controller.js
import { BridgeComponent } from "@hotwired/hotwire-native-bridge"
import { formatShortDate } from "helpers/date_helpers"

export default class extends BridgeComponent {
  static component = "share"
  static values = { dates: Object }

  shareUrl() {
    let description = this.bridgeElement.bridgeAttribute("share-description")
    if (description && this.hasDatesValue) {
      for (const [key, iso] of Object.entries(this.datesValue)) {
        description = description.replace(`%{${key}}`, formatShortDate(new Date(iso)))
      }
    }

    this.send("shareUrl", {
      title: document.title,
      url: window.location.href,
      description: description
    })
  }
}
